/**
 * GENERATED FILE — do not edit by hand. Regenerate with the audit script.
 *
 * A single-pass sweep of Thai government and state-enterprise domains run on
 * 2026-08-28 from one audit host. For each domain we requested:
 *   1. /robots.txt with Googlebot's user-agent
 *   2. /           with Googlebot's user-agent
 *   3. /           with an ordinary desktop browser user-agent
 *
 * Verdicts are deliberately conservative:
 *   'blocked'     robots.txt itself disallows everything for Googlebot. This is
 *                 authoritative — the file is public and identical for everyone.
 *   'waf-blocked' our audit host was refused (403 to every user-agent) or trapped
 *                 in a redirect loop. This is NOT proof that the real Googlebot is
 *                 blocked; it usually indicates datacentre-traffic filtering.
 *   'partial'     some paths disallowed, or a 403 shown only to a self-declared
 *                 Googlebot while a browser is served normally (anti-spoofing).
 */
export type AuditKind =
	| 'robots-disallow-all'
	| 'blanket-403'
	| 'ua-spoof-guard'
	| 'redirect-loop'
	| 'no-robots'
	| 'html-not-robots'
	| 'unreachable'
	| 'partial'
	| 'allowed';

export interface AuditRow {
	host: string;
	verdict: CrawlVerdict;
	kind: AuditKind;
	/** HTTP status for /robots.txt with Googlebot's user-agent. */
	robotsStatus: number | null;
	/** HTTP status for / with Googlebot's user-agent. */
	homeStatus: number | null;
	/** HTTP status for / with a desktop browser user-agent. */
	browserStatus: number | null;
	/** True when robots.txt carries a Googlebot-specific group that overrides `*`. */
	googlebotRule: boolean;
	snippet: string;
}

