export const AUDIT_COUNTS: Record<string, number> = {"blocked":5,"waf-blocked":20,"partial":60,"none":50,"allowed":45,"unknown":65};
export const AUDIT_KINDS: Record<string, number> = {"robots-disallow-all":5,"redirect-loop":3,"blanket-403":17,"partial":54,"ua-spoof-guard":6,"no-robots":33,"html-not-robots":17,"allowed":45,"unreachable":65};
export const AUDIT_TOTAL = 245;

export function auditByVerdict(verdict: CrawlVerdict): AuditRow[] {
	return AUDIT_ROWS.filter((r) => r.verdict === verdict);
}
export function auditByKind(kind: AuditKind): AuditRow[] {
	return AUDIT_ROWS.filter((r) => r.kind === kind);
}
export function auditFor(host: string): AuditRow | undefined {
	return AUDIT_ROWS.find((r) => r.host === host);
}
